parts.text:
[
  {
    "statement": "Ten studies evaluated the effects of coppicing on butterflies and moths.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Of the studies on coppicing's effects on butterflies and moths, eight were in the UK, one was in France, and one was in Germany.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Fourteen studies assessed the impact of clearing or opening patches in forests on butterflies and moths.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "The fourteen studies on forest clearing's impact on butterflies and moths were conducted in the UK, Finland, Japan, Sweden, the USA, Canada, the Czech Republic, and one was a review across Europe.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Six studies investigated the effects of thinning trees on butterflies and moths.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Of the six studies on tree thinning's effects, three were in the USA and one was in each of Côte d’Ivoire, Finland, and the Czech Republic.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Three replicated studies in the UK, Japan, and the Czech Republic found that cleared forest patches had a higher species richness of butterflies than unmanaged areas or closed-canopy forests.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Three replicated studies in the UK, Japan, and the Czech Republic found that cleared forest patches had a lower species richness of moths than unmanaged areas or closed-canopy forests.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A study in the Czech Republic showed that partially-cleared forest plots had more butterfly species than closed-canopy forests.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "A study in the Czech Republic showed that partially-cleared forest plots had fewer moth species than closed-canopy forests.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "One study in the UK discovered that wider woodland rides and coppiced woodland hosted more unique macro-moth species than standard-width rides or mature forest.",
    "citations": [
      "3938",
      "3939"
    ]
  },
  {
    "statement": "A UK study found that coppiced woodland had a greater butterfly species richness than unmanaged woodland.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "A separate UK study noted lower macro-moth species richness in coppiced woodland compared to mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "The species richness and diversity of fruit-feeding butterflies were similar between a thinned forest and an unmanaged forest in Côte d’Ivoire.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Rarer butterfly species were less common in the thinned forest compared to the unmanaged forest in Côte d’Ivoire.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "In the UK and France, moth and butterfly communities differed in coppiced woodlands of varying ages.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Five studies in the UK, Finland, Sweden, and Japan revealed that cleared forest patches had a higher abundance of butterflies compared to unmanaged or coppiced areas.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Butterfly species with higher abundance in cleared forest patches included the chequered blue, woodland brown, high brown fritillary, and small pearl-bordered fritillary.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A UK study indicated that wider rides had a lower abundance of macro-moths than standard-width rides or mature forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Four studies in the USA and Finland found that thinned coniferous woodland had a higher abundance of all or specialist butterflies than unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Thinned coniferous woodland was sometimes combined with other management like prescribed burning.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Two UK studies reported a higher abundance of butterflies in general in coppiced woodland versus unmanaged woodland.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Two UK studies reported a higher abundance of the heath fritillary butterfly in particular in coppiced woodland versus unmanaged woodland.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "A UK study observed lower macro-moth abundance in coppiced woodland compared to mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "The UK study that observed lower macro-moth abundance found no change based on the age of the coppice.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "The timing of management is also a factor affecting butterfly and moth communities.",
    "citations": []
  },
  {
    "statement": "One UK study showed that patches cleared 2–4 years prior had a greater abundance of heath fritillary than patches cleared 7–11 years ago.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "One UK study showed that patches cleared 2-4 years prior had a greater abundance of heath fritillary than patches cleared within the first year of clearance.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Studies in the UK, France, and Germany found butterfly abundance to be higher in woodland coppiced 2, 2–4, 5–7, or 12–15 years ago than in areas coppiced 5–11 or more than 15 years ago.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "A review across Europe reported that clearing small forest patches benefited 19 out of 67 butterfly species of conservation concern.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A UK study reported an increase in breeding sites for the pearl-bordered fritillary in cleared forest patches.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A UK study reported an increase in breeding sites for the Duke of Burgundy butterfly in cleared forest patches.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "The cleared forest patches with increased breeding sites had also been managed with cutting, grazing, and ride widening.",
    "citations": [
      "3938"
    ]
  }
]

[
  {
    "statement": "In the USA, leaving unburned patches during prescribed fires was found to be beneficial for several butterfly species.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "One replicated study reported an increase in Karner blue butterfly abundance over 2-3 years in areas with unburned patches.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "A replicated, site-comparison study found that six out of nine specialist butterfly species were more abundant in areas where unburned patches were left, compared to sites without unburned patches.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Karner blue butterflies were observed using unburned patches.",
    "citations": [
      "3879"
    ]
  },
  {
    "statement": "Rotational burning has shown mixed effects on butterfly populations in US prairies.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Four replicated studies in the USA found that under a rotational burning plan, the abundance of prairie specialist butterflies was higher on prairies that had been burned more than one, two, or four years ago compared to prairies burned more recently.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Other studies found that rotational burning in prairies resulted in more strongly declining populations of grass-skipper butterflies compared to unmanaged fields.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "Rotational burning in prairies had negative impacts on the abundance of three fritillary species in at least one region.",
    "citations": [
      "3883"
    ]
  },
  {
    "statement": "A replicated, randomized, controlled study in the USA found no difference in the species richness of butterflies between prairies managed with annual rotational burning and prairies under complete burning.",
    "citations": [
      "3883"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of restricting the use of polarized light on butterflies and moths.",
    "citations": [
      "3903"
    ]
  },
  {
    "statement": "No studies were found that assessed the effects of restricting the timing of lighting to conserve areas with natural light regimes.",
    "citations": [
      "3901"
    ]
  },
  {
    "statement": "No studies were found that assessed the effects of the use of glazing treatments to reduce light spill from inside lit buildings.",
    "citations": [
      "3905"
    ]
  }
]

[
  {
    "statement": "Sixteen studies evaluated the effects of translocating butterflies and moths to re-establish populations within their former range.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Eight studies reported that translocated populations of adult butterflies and moth eggs persisted for 2-12 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Eight studies reported that translocated populations of adult butterflies and moth eggs increased in abundance.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Three other studies reported that some translocated populations persisted for 1-49 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Three other studies reported that some translocated populations increased in abundance and colonized new sites.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Three other studies reported that some translocated populations died out within 0-7 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that 25% of translocated and released captive-bred butterfly populations survived for at least three years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that 38% of translocated and released captive-bred butterfly populations died out within three years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "One review found that 8% of translocated and released captive-bred butterfly populations were known to have survived for more than 10 years.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "A review reported that translocated populations of large copper adults and caterpillars survived for up to 38 years but ultimately died out or required supplementation.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Nineteen years after translocation, a population of large blue butterflies had similar genetic diversity to their Swedish source population.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "Four studies evaluated translocating butterflies and moths to establish populations outside of their known range.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "Two studies reported that populations of Gillette's checkerspot, small skipper, and marbled white butterflies translocated outside of their native range persisted and increased in abundance over eight and 28 years.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "A third study reported that a translocated population of Gillette's checkerspot died out within one year.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "One study found that 69 years after translocation, an introduced population of the small mountain ringlet butterfly had similar genetic diversity to its source population.",
    "citations": [
      "3911"
    ]
  },
  {
    "statement": "Studies found that the survival of translocated large blue caterpillars was higher in nests of the ant Myrmica sabuleti without queen ants present.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "The survival of translocated large copper caterpillars was higher than that of released, captive-bred caterpillars.",
    "citations": [
      "3909"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of introducing mated females to increase genetic diversity.",
    "citations": [
      "3912"
    ]
  }
]

[
  {
    "statement": "Gardens that do not use insecticides and herbicides were found to have a higher abundance of butterflies.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "Planting native species in gardens has been shown to increase the species richness and abundance of butterflies and moths.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Planting native species along road verges has been shown to increase the species richness and abundance of butterflies and moths.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "In some cases, monarch butterfly adults were found to use milkweed in gardens more than in meadows.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "The survival of pipevine swallowtail eggs was lower on pipevine planted in gardens than in natural sites.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "The survival of pipevine swallowtail caterpillars was lower on pipevine planted in gardens than in natural sites.",
    "citations": [
      "3842"
    ]
  }
]

[
  {
    "statement": "In US forests, one study found that shelterwood harvesting resulted in a higher species richness of macro-moths compared to clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "One study found that macro-moth richness levels in forests after shelterwood harvesting were similar to those in unharvested forests.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "Another study found that moth species richness recovered faster after shelterwood harvesting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "A study found that moth species richness after shelterwood harvesting was similar to that found after clearcutting.",
    "citations": [
      "3871"
    ]
  },
  {
    "statement": "One study found that thinning a forest resulted in higher macro-moth species richness compared to clearcutting.",
    "citations": [
      "3868"
    ]
  },
  {
    "statement": "Single tree selection harvesting resulted in a similar species richness of moths when compared to clearcutting.",
    "citations": [
      "3867",
      "3868"
    ]
  },
  {
    "statement": "Group selection harvesting resulted in a similar species richness of moths when compared to clearcutting.",
    "citations": [
      "3867",
      "3868"
    ]
  },
  {
    "statement": "In multiple studies, unharvested forests had a higher species richness of moths than those managed by any harvesting methods.",
    "citations": [
      "3867",
      "3868",
      "3871"
    ]
  },
  {
    "statement": "Unharvested forests had a higher species richness of moths than forests managed by clearcutting, shelterwood, single tree selection, or group selection.",
    "citations": [
      "3867",
      "3868",
      "3871"
    ]
  }
]

[
  {
    "statement": "Altering mowing regimes on greenspaces and road verges affects butterflies and moths.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Less frequently mown or unmown urban greenspaces had a higher species richness of butterflies and moths than more frequently mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Less frequently mown or unmown urban greenspaces had a higher diversity of butterflies and moths than more frequently mown areas.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Unmown public parks and road verges had a higher abundance of all adult butterflies.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Roadsides mown in late summer had more ringlet butterflies than those mown in mid-summer.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Road verges mown less frequently had fewer dead butterflies killed by traffic.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Road verges mown later in the summer had fewer dead butterflies killed by traffic.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Scarce copper butterflies more frequently occupied less frequently mown urban grasslands.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "One study found that the management of road verges and land under power lines did not affect butterfly species richness.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "In the Netherlands, butterflies were only recorded on mowed verges where hay was removed.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Restored roadside prairies in the USA with restricted herbicide application had greater butterfly species richness and abundance compared to verges with no herbicide restrictions.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "Restored roadside prairies in the USA with restricted herbicide application had a lower butterfly mortality risk compared to verges with no herbicide restrictions.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "A Canadian study found that transmission lines that were not sprayed or mown had a similar species richness of butterflies to those that were sprayed and mown.",
    "citations": [
      "3899"
    ]
  },
  {
    "statement": "In Finland, land under power lines managed by mechanical cutting had a higher species richness of butterflies than unmanaged land.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "In Finland, the highest butterfly species richness was observed on land under power lines 2-4 years after scrub and tree clearance.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "A study in Canada found similar butterfly species richness under power lines and on road verges, regardless of whether the areas were mown once or twice a year, or left unmown.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Mechanically cut land under power lines had a higher abundance of butterflies than unmanaged land.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Land under power lines and on road verges managed by mowing had a lower abundance of some butterfly species when compared to unmown areas.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Land under power lines and on road verges managed by mowing had a similar abundance of other butterfly species when compared to unmown areas.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "The time since management plays a role in butterfly abundance.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Chequered skipper abundance was highest in areas cleared within the last two years.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Pearl-bordered fritillaries used areas where scrub had been cleared one or two years earlier.",
    "citations": [
      "3855"
    ]
  },
  {
    "statement": "Pearl-bordered fritillaries did not use areas where scrub had been cleared three or more years ago.",
    "citations": [
      "3855"
    ]
  }
]

[
  {
    "statement": "A study in the UK found that excluding invertebrate herbivores resulted in a higher density of pearl-bordered fritillary butterflies.",
    "citations": [
      "3885"
    ]
  },
  {
    "statement": "Ten studies have been conducted on the exclusion of vertebrate herbivores.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Two of four studies on excluding vertebrate herbivores found that excluding non-native pigs and deer resulted in a greater species richness of butterflies and macro-moths.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Two of four studies on excluding vertebrate herbivores found mixed effects on species richness when excluding elk.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "A global systematic review found that removing or reducing grazing by wild or domestic herbivores in temperate and boreal forests did not affect the species richness of butterflies and moths.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "Five of eight studies found that excluding deer, sheep, pigs and other large herbivores resulted in a higher abundance of butterflies, moths and caterpillars.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "One global systematic review found that a reduction or removal in grazing by wild or domestic herbivores in temperate and boreal forests led to an increase in the abundance of butterflies and moths.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "One study found that all Glanville fritillary caterpillar nests survived in an area where sheep were excluded.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "In one study, 88% of Glanville fritillary caterpillar nests survived in a grazed area.",
    "citations": [
      "3891"
    ]
  },
  {
    "statement": "One study found that fewer Glanville fritillary caterpillar nests were damaged in an area where sheep were excluded.",
    "citations": [
      "3891"
    ]
  }
]

[
  {
    "statement": "Ten studies looked at the effects of converting arable land to permanent grassland on butterflies and moths.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Grasslands restored from bare soil by seeding produced butterfly communities that grew to increasingly resemble existing high-quality grasslands over the first 10 years after establishment.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Created grasslands and abandoned cropland that were 4–5 years old were found to have a higher species richness of butterflies and moths compared to conventionally managed grassland or cultivated farms.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Grasslands established by sowing grasses, legumes, and other forbs, or perennial grass mixes, had a higher species richness and abundance of butterflies when compared to grasslands established with grass-only mixes.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Restored grassland had a higher abundance of moths than conventional grassland.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Restored grassland had a similar abundance of moths to semi-natural grasslands.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Six studies assessed the effects of creating or restoring species-rich, semi-natural grassland, which included actions like clearing scrub.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Butterfly communities in semi-natural grasslands restored by clearing scrub and reintroducing grazing or mowing were distinct from communities in already species-rich grasslands.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Butterfly communities in restored semi-natural grasslands did not grow more similar over time to communities in already species-rich grasslands.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "One study discovered that semi-natural grasslands restored through scrub clearance and grazing had a species richness of butterflies and burnet moths comparable to that of both unrestored and continuously managed grassland.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Another study revealed that semi-natural grasslands restored by cattle grazing had a lower species richness of butterflies and day-flying moths than unrestored and continuously managed grasslands.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Two studies discovered that grasslands restored by cattle grazing had a lower total abundance of butterflies and day-flying moths than unmanaged, abandoned grasslands.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "The abundance of butterflies and burnet moths was found to be similar in grasslands restored by scrub clearing and grazing or mowing to the abundance in unmanaged grasslands and continuously managed grasslands.",
    "citations": [
      "3955"
    ]
  }
]

[
  {
    "statement": "Wetland creation in Sweden increased macroinvertebrate diversity, including butterflies and moths.",
    "citations": [
      "3949"
    ]
  },
  {
    "statement": "Species richness in created wetlands in Sweden increased with wetland age, becoming similar to mature ponds.",
    "citations": [
      "3949"
    ]
  },
  {
    "statement": "A wetland prairie in the USA restored through seeding willow dock and seasonal flooding had a higher abundance of great copper eggs than degraded, unflooded prairie.",
    "citations": [
      "3949"
    ]
  },
  {
    "statement": "The survival of great copper eggs and caterpillars was lower in a wetland prairie in the USA restored by planting native seed mixes and annual flooding compared to degraded, unflooded prairie.",
    "citations": [
      "3949"
    ]
  },
  {
    "statement": "Restored wetland prairie in the USA was used more by adult great copper butterflies than degraded, unflooded prairie.",
    "citations": [
      "3949"
    ]
  },
  {
    "statement": "Fens in Switzerland managed by mowing had a greater species richness of butterflies than fens managed by cattle grazing.",
    "citations": [
      "3950"
    ]
  },
  {
    "statement": "A study in the Netherlands observed fewer large copper eggs in recently cut fens compared to uncut fens.",
    "citations": [
      "3950"
    ]
  },
  {
    "statement": "Studies in the Netherlands found that the survival of large copper caterpillars was lower in recently cut fens compared to uncut fens.",
    "citations": [
      "3950"
    ]
  },
  {
    "statement": "Studies in the Netherlands found that the survival of large copper caterpillars was lower in fens cut in autumn or winter compared to uncut fens.",
    "citations": [
      "3950"
    ]
  }
]

[
  {
    "statement": "Coniferous forest restored by burning 1-2 years prior, or burned once in the last 20 years, had a higher species richness of butterflies than unburned forest.",
    "citations": [
      "3877"
    ]
  },
  {
    "statement": "Pine forest restored 1-2 years ago by burning, in combination with thinning, had a greater abundance of butterflies than unburned forest.",
    "citations": [
      "3877"
    ]
  },
  {
    "statement": "The abundance of Karner blue butterflies increased over 2-3 years in oak savannas and prairies where unburned patches were left during prescribed burning.",
    "citations": [
      "3879"
    ]
